D[992]={"^Reduces the cooldown of your Hand of Protection by (.-) sec%.\n\nIncreases the duration of your Hand of Freedom by (.-) sec and Hand of Sacrifice by (.-) sec%.%s*$","Reduz a recarga de sua Mão da Proteção em {{1}} s.\n\nAumenta a duração de sua Mão da Liberdade em {{2}} s e de sua Mão do Sacrifício em {{3}} s."}
D[3573]={"^Reduces the Energy cost of |cffffffffMotivating Strike|r by (.-)%%%.%s*$","Reduz o custo de Energia de |cffffffffGolpe Motivador|r em {{1}}%."}
D[3578]={"^Increases the duration of |cffffffffStandard of Valiance|r and |cffffffffBallad of the Dragonslayer|r by (.-)%%%.%s*$","Aumenta a duração de |cffffffffEstandarte de Bravura|r e |cffffffffCanto do Assassino de Dragões|r em {{1}}%."}
D[3579]={"^Increases the duration of |cffffffffStandard of Valiance|r and |cffffffffBroad Sweep|r by (.-)%%%.%s*$","Aumenta a duração de |cffffffffEstandarte de Bravura|r e |cffffffffVarredura Ampla|r em {{1}}%."}
D[3778]={"^Swing at up to (.-) enemies in front of you, dealing (.-)%% Weapon Damage plus (.-) and reduces their attack power by (.-) for (.-)%.%s*$","Atinge até {{1}} inimigos à sua frente, causando {{2}}% de dano da arma além de {{3}} e reduz seu poder de ataque em {{4}} durante {{5}}."}
D[3782]={"^Fortify your defenses, reducing all damage taken by (.-)%% and gaining immunity to stun effects for (.-)%.%s*$","Fortalece suas defesas, reduzindo todo o dano recebido em {{1}}% e tornando você imune a efeitos de atordoamento durante {{2}}."}
D[3944]={"^An instant strike that causes Weapon Damage plus (.-), granting |cff66ccffMotivation|r%.%s*$","Um ataque instantâneo que causa dano da arma mais {{1}}, concedendo |cff66ccffMotivação|r."}
D[3979]={"^Give the final verdict to your target, dealing (.-) Physical damage and healing you for 15%% of your maximum health%.\n\nOnly usable on enemies below 20%% health%. Killing blows reset the cooldown of this ability%.%s*$","Determina a sentência final ao alvo, causando {{1}} de dano Físico e curando você por 15% de sua vida máxima.\n\nSomente utilizável em inimigos com menos de 20% de vida. Os golpes mortais reiniciam a recarga desta habilidade."}
D[3989]={"^A nearby Standard of Valiance is damaging you and slowing your movement speed%.%s*$","Um Estandarte de Bravura próximo está causando a você dano e reduz sua velocidade de movimento."}
D[4173]={"^Throw down a |cffffffffStandard of Valiance|r for (.-), nearby enemies within the area take (.-) Physical Damge every (.-) sec and their movement speed is slowed by (.-)%%%.\n\nOnly 1 |cffffffffStandard|r can be active at a time%.%s*$","Lança um |cffffffffEstandarte de Bravura|r durante {{1}}. Inimigos próximos dentro da área recebem {{2}} de dano Físico a cada {{3}} s e têm a velocidade de movimento reduzida em {{4}}%.\n\nApenas 1 |cffffffffEstandarte|r pode ficar ativo por vez."}
D[4174]={"^Charge an enemy, dealing (.-) Physical damage and stunning them for (.-)%.%s*$","Investe contra um inimigo, causando {{1}} de dano Físico e atordoando-o durante {{2}}."}
D[4306]={"^Inflict Weapon Damage plus (.-) to up to (.-) enemies in a (.-) yd line and reduce their movement speed by (.-)%% for (.-)%.%s*$","Causa dano da arma mais {{1}} até {{2}} inimigos em uma linha de {{3}} m e reduz sua velocidade de movimento em {{4}}% durante {{5}}."}
D[4307]={"^|cff66ccffGrants Motivation|r\nSlam the ground, dealing (.-) Physical Damage, scaling with defense rating to nearby enemies and reducing their casting speed by (.-)%% for (.-)%.\n\nDeals (.-)%% increased damage to enemies affected by |cffffffffLine Formation|r%.%s*$","|cff66ccffConcede Motivação|r\nGolpeia o chão, causando {{1}} de dano Físico aos inimigos próximos, com o dano escalando com seu Índice de Defesa, e reduzindo a velocidade de lançamento deles em {{2}}% durante {{3}}.\n\nCausa {{4}}% a mais de dano a inimigos afetados por |cffffffffFormação em Linha|r."}
D[4308]={"^|cff66ccffGrants Motivation|r\nSlam the ground, dealing (.-) Physical Damage, scaling with defense rating to nearby enemies%.\n\nDeals (.-)%% increased damage to enemies affected by |cffffffffLine Formation|r%.%s*$","|cff66ccffConcede Motivação|r\nGolpeia o chão, causando {{1}} de dano Físico aos inimigos próximos, com o dano escalando com seu Índice de Defesa.\n\nCausa {{2}}% a mais de dano a inimigos afetados por |cffffffffFormação em Linha|r."}
D[4312]={"^Mark an ally for |cfffeff9e(.-)|r, causing them to grant |cffffffffMotivation|r to nearby allies when they interrupt an enemy%.\n\nOnly 1 ally can be affected by Feats of Glory at a time%.%s*$","Marca um aliado por |cfffeff9e{{1}}|r, fazendo com que ele conceda |cffffffffMotivação|r aos aliados próximos ao interromper um inimigo.\n\nApenas 1 aliado pode ser afetado por |cffffffffFaçanhas de Glória|r por vez."}
