D[73670]={"^Deals (.-) Damage to all enemies within 20 yards%.%s*$","Causa {{1}} de dano a todos os inimigos dentro de 20 metros."}
D[73862]={"^Increases your Block Value by (.-)%% and the armor gained from your shield by (.-)%%%. Stacks 5 times%. Lasts (.-)%.%s*$","Aumenta seu Valor de Bloqueio em {{1}}% e a armadura obtida por seu escudo em {{2}}%. Acumula 5 vezes. Dura {{3}}."}
D[73966]={"^Transforms |cffffffffPulverize|r into |cffffffffSpear Throw|r and increases the critical damage and critical strike chance of |cffffffffSpear Throw|r by (.-)%%%.%s*$","Transforma |cffffffffPulverizar|r em |cffffffffLançamento de lança|r e aumenta o dano crítico e a chance de acerto crítico de |cffffffffLançamento de lança|r em {{1}}%."}
D[76233]={"^|cffffffff2 Charges, 6 sec recharge|r\nThrow your shield at an enemy and up to (.-) nearby enemies and deal (.-) Physical damage%. Scales with modifiers to |cffffffffPulverize|r%. |cFFFFFFFFShield Toss|r cannot be blocked, dodged or parried%.\n\nEvery 2nd |cffffffffShield Toss|r will reduce all damage enemies deal by (.-)%% for (.-)%.%s*$","|cffffffff2 Cargas, 6 s de recarga|r\nLança seu escudo um inimigo e até {{1}} inimigos próximos, causando {{2}} de dano Físico. Escala com modificadores de |cffffffffPulverizar|r. |cFFFFFFFFLançamento de escudo|r não pode ser bloqueado, esquivado nem aparado.\n\nCada 2ª |cffffffffLançamento de escudo|r reduzirá o dano que os inimigos causem {{3}}% durante {{4}}."}
D[76282]={"^|cffffffff2 Charges|r\n|cffffffff6 sec recharge|r\nThrow your shield at an enemy and up to 8 nearby enemies dealing (.-) Physical Damage%. Scales with modifiers to |cffffffffPulverize|r%.\n\nEvery 2nd |cffffffffShield Toss|r will reduce all damage enemies deal to you by 5%% for 5 sec%.%s*$","|cffffffff2 Cargas|r\n|cffffffff6 s recarga|r\nLança seu escudo um inimigo e até 8 inimigos próximos causando {{1}} de dano Físico. Escala com modificadores de |cffffffffPulverizar|r.\n\nCada 2ª |cffffffffLançamento de escudo|r reduz o dano que os inimigos te causam em 5% durante 5 s."}
D[76350]={"^Casting |cffffffffGrand Entrance|r now instantly triggers a free |cffffffffGlorious Arena|r%.%s*$","Lançamento de |cffffffffEntrada Triunfal|r agora ativa um |cffffffffGloriosa Arena|r grátis."}
D[76376]={"^Casting |cFFFFFFFFBallad of the Conqueror|r now has a (.-)%% chance to reset the cooldown of |cffffffffRam|r%.%s*$","O lançamento de |cFFFFFFFFCanto do Conquistador|r tem agora {{1}}% de chance de restaurar a recarga de |cffffffffAríete|r."}
D[76377]={"^Casting |cffffffffPulverize|r now has a (.-)%% chance to reset the cooldown of |cffffffffRam|r%.%s*$","O lançamento de |cffffffffPulverizar|r tem agora {{1}}% de chance de restaurar a recarga de |cffffffffAríete|r."}
D[76414]={"^Casting |cffffffffBroad Sweep|r now refreshes 1 charge, and casting |cffffffffCenturion Strike|r now refreshes 2 charges, of |cffffffffReprisal|r%.%s*$","Lançar |cffffffffVarredura Ampla|r restaura 1 carga de |cffffffffGolpe do Centurião|r, enquanto lançar |cffffffffRetaliação|r restaura 2 cargas."}
D[76602]={"^Each stack can be consumed by |cFFFFFFFFBallad of the Conqueror|r to deal an additional (.-) Physical Damage and reduce the cooldown of |cffffffffGlorious Arena|r by (.-)%%%.\n\nUpon reaching 5 stacks, the stacks are instantly consumed to stun the enemy for (.-)%.%s*$","Cada acúmulo pode ser consumida com |cFFFFFFFFCanto do Conquistador|r para causar {{1}} de dano Físico adicional e reduz a recarga de |cffffffffGloriosa Arena|r em {{2}}%.\n\nAo alcançar 5 acúmulos, eles são consumidos instantaneamente para atordoar contra o inimigo durante {{3}}."}
D[76603]={"^Each stack can be consumed by |cffffffffPulverize|r to deal an additional (.-) Physical Damage and reduce the cooldown of |cffffffffGlorious Arena|r by (.-)%%%.\n\nUpon reaching 5 stacks, the stacks are instantly consumed to stun the enemy for (.-)%.%s*$","Cada acúmulo pode ser consumida com |cffffffffPulverizar|r para causar {{1}} de dano Físico adicional e reduz a recarga de |cffffffffGloriosa Arena|r em {{2}}%.\n\nAo alcançar 5 acúmulos, eles são consumidos instantaneamente para atordoar contra o inimigo durante {{3}}."}
D[76643]={"^Damage dealt by |cffffffffHammer of Kings|r now reduces the damage taken from the next strike against you by 2%% for (.-), stacking 10 times%.%s*$","O dano causado por |cffffffffMartelo dos Reis|r agora reduz o dano recebido próximo golpe contra você em 2% durante {{1}}, acumulando-se 10 vezes."}
D[76763]={"^Makes melee attacks generate a stack of |cFFFFFFFFBattle Inspired|r which allows usage of Song of Battle at 5 stacks%.%s*$","Permite que os ataques corpo a corpo gerem um acúmulo de |cFFFFFFFFInspirado ao Combate|r, o qual permite usar Canto do Combate com 5 acúmulos."}
D[76939]={"^Successful blocks and |cffffffffRams|r now reduces the remaining cooldown of |cffffffffStandard of Valiance|r by (.-) sec and grants |cffffffffEarthsplitter|r for (.-)%.%s*$","Os bloqueios bem-sucedidos e |cffffffffEmpurrões|r agora reduzem a recarga restante de |cffffffffEstandarte de Bravura|r em {{1}} s e concedem |cffffffffDivisor de Terras|r em {{2}}."}
D[76980]={"^|cFF66DDFFLevel 20 Passive|r\n|cFFFFFFFFPulverize|r and |cffffffffBroad Sweep|r now have a (.-)%% chance to grant you |cffffffffWarmaster|r%.%s*$","|cFF66DDFFPassivo de Nível 20|r\n|cFFFFFFFFPulverizar|r e |cffffffffVarredura Ampla|r agora têm {{1}}% de chance de conceder a você o |cffffffffGeral|r."}
D[77080]={"^Critical strikes cause your next |cffffffffPulverize|r within 6 sec to be free of cost and deal 25%% increased damage%.%s*$","acertos críticos fazem que seu próximo |cffffffffPulverizar|r dentro de 6 s seja gratuito e cause dano aumentado em 25%."}
D[77486]={"^Blocking an attack grants you a stack of |cffffffffParagon|r for (.-)%. Can only occur once every 0%.5 sec%.\n\nAt (.-) stacks, your |cffffffffHeavy Blow|r transforms into |cffffffffParagon Smash|r for (.-)%.\n\nCasting |cffffffffHeavy Blow|r instantly grants 3 stacks of this effect%.%s*$","Bloquear um ataque concede a você um acúmulo de |cffffffffParagão|r para {{1}}. Só pode ocorrer uma vez a cada 0,5 s.\n\nAo atingir {{2}}3 Acúmulos, seu |cffffffffGolpe Pesado|r é transformado em |cffffffffGolpe destruidor|r durante {{3}}.\n\nLançar |cffffffffGolpe Pesado|r concede a você instantaneamente 3 acúmulos deste efeito."}
D[77487]={"^Blocking an attack grants a stack of |cffffffffBastion|r%. At 10 stacks, your |cffffffffTower Formation|r transforms into |cffffffffBastion|r%.\n\n|cffffffffTower Formation|r instantly grants 10 stacks of this effect%.%s*$","Bloquear um ataque concede a você um acúmulo de |cffffffffBastião|r. A partir das 10 acúmulos, seu |cffffffffFormação de torre|r é transformado em |cffffffffBastião|r.\n\n|cffffffffFormação de torre|r concede instantaneamente 10 acúmulos deste efeito."}
D[77671]={"^Blocking attacks now has a (.-)%% chance to grant you |cFFFFFFFFHammer of Kings|r for (.-) sec%. \n\nIf |cffffffffHammer of Kings|r is already active, you increase the duration by 4 sec%.%s*$","Bloquear ataques agora tem {{1}}% de chance de conceder |cFFFFFFFFMartelo dos Reis|r durante {{2}} s.\n\nSe |cffffffffMartelo dos Reis|r já estiver ativo, sua duração aumenta em 4 s."}
D[79005]={"^Deals (.-) Physical damage to all nearby enemies%.\n\nIncreases your chance to block by (.-)%% and each block reduces the cooldown of |cffffffffBrace|r by (.-) sec%. Lasts for 5 blocks or (.-)%.\n\nScales with modifiers to |cffffffffHeavy Blow|r%.%s*$","causa {{1}} de dano Físico todos os inimigos próximos.\n\nAumenta sua chance de {{2}}% bloquear e cada bloqueio reduz a recarga de |cffffffffPreparar-se|r em {{3}} s. Dura para 5 blocos ou {{4}}.\n\nEscala com modificadores a |cffffffffGolpe Pesado|r."}
D[79021]={"^While |cffffffffRaise Shield|r is on cooldown it transforms into |cffffffffSpear Throw|r%.%s*$","Enquanto que |cffffffffErguer Escudo|r está em recarga é transformado em |cffffffffLançamento de lança|r."}
D[79259]={"^|cFF66DDFFLevel 40 Passive|r\nCasting |cffffffffRam|r and |cffffffffPulverize|r now increases your attack power based on your block rating for (.-)%.%s*$","|cFF66DDFFPassivo de Nível 40|r\nLançar |cffffffffAríete|r e |cffffffffPulverizar|r agora aumenta seu poder de ataque baseado em seu índice para bloquear durante {{1}}."}
D[82517]={"^\nTransforms your Intervene into Vanguard%.%s*$","\nTransforma seu Intervém em Vanguarda."}
D[82518]={"^Replaces your Intervene with Vanguard%.%s*$","Substitui seu Intervenção com Vanguarda."}
D[82519]={"^Charge toward the target of your Vigilance, forming a Vanguard%. While you remain close you follow up their auto attacks with your own attack, dealing (.-)%% weapon damage%. This attack can only occur once every 3 seconds%. Lasts for (.-)%.%s*$","Avança até o alvo da sua Vigilância, formando uma Vanguarda. Enquanto permanecer perto dele, você acompanha os ataques automáticos dele com um ataque seu, causando {{1}}% do dano da arma. Esse ataque só pode ocorrer uma vez a cada 3 s. Dura {{2}}."}
D[82520]={"^Charge toward the target of your Vigilance, forming a Vanguard%. While you remain close you follow up their auto attacks with your own%. Lasts for (.-)%.%s*$","Forma uma Vanguarda contra o alvo de seu Vigilance. Enquanto você mantenha perto, continua seus ataques automáticos com os seus próprios. Dura {{1}}."}
D[84899]={"^Grants |cffffffffArcing Strike|r an 18%% chance to cause an Injury to the target, slowing their movement speed by (.-)%% for (.-)%.\n\nUsing |cffffffffTendon Slash|r against enemies with an Injury consumes the effect to deal (.-)%% increased damage%.%s*$","Proporciona a |cffffffffGolpe em Arco|r 18% de chance para causar um Injurio o alvo, reduzindo sua velocidade de movimento em {{1}}% durante {{2}}.\n\nUsando |cffffffffTalho de Tendão|r contra inimigos com Injurio consome o efeito para causar um aumento de {{3}}%."}
D[85149]={"^Pulverize nearby enemies, interrupting their spellcasting for (.-)%.%s*$","Pulveriza os inimigos próximos, interrompendo qualquer conjuração de feitiços durante {{1}}."}
D[85318]={"^Have a 2%% chance when struck in combat of increasing armor by (.-) for (.-)%.%s*$","Tem 2% de chance de aumentar a armadura {{1}} durante {{2}} ao ser atingido em combate."}
D[90258]={"^You have a chance each time you are hit to gain (.-) haste rating for (.-)%.%s*$","Sempre que você é atingido tem uma chance de ganhar {{1}} rating de aceleração durante {{2}}."}
D[91314]={"^The mental exhaustion of the Manticron Cube wearies even the most powerful of sorcerers%.%s*$","A extenuação mental do cubo Manticron esgotaté ao conjurador mais poderoso."}
D[93685]={"^Prevents use of Obedience Crystals%.%s*$","Impede o uso de Cristais de Obediência."}
D[94575]={"^Periodically draws the attention of all enemy units within (.-) yards and causes additional high threat to all enemies within (.-) yards%.%s*$","Atrai periodicamente a atenção de todas as unidades inimigas a menos de {{1}} m e causa uma ameaça adicional elevada contra todos os inimigos que se encontrem um raio de {{2}} m."}
D[95387]={"^Inflicts (.-) Nature damage and an additional (.-) Nature damage every (.-) sec for (.-)%.%s*$","Causa {{1}} de dano de Natureza e {{2}} de dano de Natureza extras a cada {{3}} s durante {{4}}."}
D[97419]={"^Reduces the cooldown of your Hand of Protection by (.-) sec and increases the duration of your Hand of Freedom by (.-) sec%.%s*$","Reduz a recarga de sua Mão de proteção {{1}} s e Aumenta a duração de Mão de liberdade {{2}} s."}
D[97767]={"^Reduces the cooldown of your Hand of Protection by (.-) min and increases the duration of your Hand of Freedom by (.-) sec%.%s*$","Reduz a recarga de sua Mão de proteção {{1}} min e Aumenta a duração de Mão de liberdade {{2}} s."}
D[98319]={"^Utter your most |cffffffffInspiring Speech|r, reducing an allies damage taken by (.-)%% for (.-)%. Can be used while moving%.\n\nAlso reduces the damage taken of party and raid members within (.-)|r yds that are affected by |cff66ccffMotivation|r, and cleanses 1 harmful Magic Effect from them%.%s*$","Profere seu mais |cffffffffDiscurso Inspirador|r, reduzindo em {{1}}% o dano recebido por um aliado durante {{2}}. Pode ser usado em movimento.\n\nTambém reduz o dano recebido pelos membros do grupo e da raide em um raio de {{3}}|r m afetados por |cff66ccffMotivação|r e remove deles 1 efeito Mágico nocivo."}
