T[10812]={"^Movement Speed reduced by (.-)%%%.\n\nUsing Tendon Slash against this target will consume the effect to deal additional damage%.%s*$","A velocidade de movimento é reduzida em {{1}}%.\n\nUsar Corte de Tendão contra este alvo consumirá o efeito para causar dano adicional."}
T[10815]={"^The Guardian's Motivating Strike ability can trigger bonus damage against this target while they are in Offensive Pose%.%s*$","A habilidade Motivadora acerto do Guardião pode causar um dano adicional contra este alvo enquanto estiver em Postura Ofensiva."}
T[10866]={"^|cffffffffPulverize|r grants a stack of |cffffffffGlory|r for (.-)%.\n\nAt 3 stacks, your next |cffffffffDeath Ram|r deals double damage%.%s*$","|cffffffffPulverizar|r concede um acúmulo de |cffffffffGlória|r para {{1}}.\n\nCom 3 acúmulos, seu próximo |cffffffffCarga da Morte|r causa o dobro de dano."}
T[11096]={"^Your Refuse To Die passive is disabled%.%s*$","Seu Recusar-se a Morrer passivo está desativado."}
T[11136]={"^Arcing Strike deals (.-)%% additional damage, and the cost of your next Linebreaker is reduced by (.-)%%%.%s*$","acerto Gelonte causa {{1}}% de dano adicional, e o custo de seu próximo Rompedor de Linhas é reduzido em {{2}}%."}
T[11363]={"^Your next Glorious Execution will incur no cooldown%.%s*$","Sua próxima Execução Gloriosa não terá recarga."}
T[12521]={"^Each ally within ten yards empowers the Warlord to greater heights%.\n\nDamage taken reduced by (.-)%%%.\n\nDamage dealt increased by (.-)%%%.%s*$","Cada aliado dentro de dez metros potência ao Marechal de Campo até maiores alturas.\n\nO dano recebido é reduzido em {{1}}%.\n\nO dano causado aumenta em {{2}}%."}
T[12920]={"^Your auto attacks are followed up by an attack from the Warrior that used Vanguard%.%s*$","Seus ataques automáticos são seguidos por um ataque do Guerreiro que usou Vanguarda."}
T[12921]={"^Your auto attacks are followed up by an auto attack from the Warrior that used Vanguard%.%s*$","Seus ataques automáticos são seguidos por um ataque automático do Guerreiro que usou Vanguarda."}
T[13399]={"^Grants Arcing Strike a chance to cause an Injury to the target, reducing their |cffff8100Movement Speed|r by (.-)%% for (.-)%.\n\nTendon Slash against enemies with an Injury consumes the effect to deal (.-)%% increased damage%.%s*$","Concede a Golpe em Arco uma chance de causar um Ferimento no alvo, reduzindo sua |cffff8100Velocidade de Movimento|r em {{1}}% durante {{2}}.\n\nTalho de Tendão contra inimigos com Ferimento consome o efeito para causar {{3}}% a mais de dano."}
T[14153]={"^Consumes all stacks of your Lacerate or Thrash bleeds to deal (.-) damage to your target and grants you enrage for (.-) seconds%. \n\nPulverize is only usable when the target has at least 3 stacks of Lacerate or Thrash on them%.%s*$","Consome todos os acúmulos dos efeitos de sangramento de Lacerar ou Espancar no alvo para causar {{1}} de dano e concede Enfurecimento durante {{2}} s.\n\nPulverizar só pode ser usado quando o alvo tiver pelo menos 3 acúmulos de Lacerar ou Espancar."}
T[14169]={"^Damage taken from the Gladiator increased by (.-)%%%.Physical Damage increased by (.-)%%%s*$","O dano recebido do Gladiador aumenta em {{1}}%. O dano Físico aumenta em {{2}}%."}
T[14170]={"^Damage taken from the Gladiator increased by (.-)%%%.%s*$","O dano recebido do Gladiador aumenta em {{1}}%."}
T[14171]={"^Physical Damage increased by (.-)%%%s*$","O dano Físico aumenta em {{1}}%."}
T[14306]={"^A nearby Standard of Valiance is damaging you and slowing your movement speed%.%s*$","Um Estandarte de Bravura próximo está causando a você dano e reduz sua velocidade de movimento."}
T[14326]={"^At 3 stacks, your next Pulverize transforms into Shield Toss%.%s*$","Com 3 acúmulos, seu próximo Pulverizar transforma-se em Lançamento de Escudo."}
T[14345]={"^Block chance increased by (.-)%%%. Block Value increased by (.-)%%%. Whenever you are attacked, expend 1 charge to deal (.-) damage to the attacker%.  (.-) charges%.%s*$","Chance de bloqueio aumentada em {{1}}%. Valor de bloqueio aumenta em {{2}}%. Sempre que te ataquem, gasta 1 carga para causar {{3}} dano ao atacante. {{4}} cargas."}
T[14439]={"^Deals Physical Damage%.%s*$","Causa dano Físico."}
T[14490]={"^Dodge chance increased by (.-)%%, Movement Speed increased by (.-)%%, Attack Power increased by (.-)%% of your Agility%. Increases the damage dealt by Death Ram and Death Sentence by 50%%%.\n\nThis buff is removed if you equip an item in the Head, Shoulder, Chest, Wrist or Hand slots%.%s*$","Aumenta sua chance de esquiva em {{1}}%, sua velocidade de movimento em {{2}}% e seu poder de ataque em {{3}}% da Agilidade. Aumenta em 50% o dano causado por Carga da Morte e Sentença de Morte.\n\nEste benefício é removido se você equipar um item nos espaços de Cabeça, Ombros, Torso, Pulsos ou Mãos."}
T[14581]={"^Reduces the cooldown of |cffffffffLinebreaker|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffQuebra-Linhas|r em {{1}} s."}
T[14582]={"^Next 2 Rams or Pulverizes will ignore (.-)%% of your target's armor%.%s*$","A próxima 2 Carga ou Pulveriza ignorará {{1}}% da armadura de seu alvo."}
T[14585]={"^Dealing 20%% of the damage dealt by Forgehammer every (.-) sec%.%s*$","Causa 20% do dano causado por Forgehammer a cada {{1}} s."}
T[14804]={"^Vanguard X%-42 mechsuit abilities enabled%.%s*$","Habilidades do Traje Mecânico Vanguarda X-42 ativadas."}
T[14846]={"^Parry chance increased by 100%%%. Deals (.-) damage to attackers and heal for (.-) health whenever you parry and expend a charge%.%s*$","A chance de aparar aumenta em 100%.\n\nCausa {{1}} de dano aos atacantes e cura em {{2}} vida sempre que paras e gasta uma carga."}
T[14872]={"^Next 3 |cffffffffValiant Strikes|r and |cffffffffRams|r deal (.-)%% increased damage and grant |cffffffffTempo|r%.\n\nUpon expiration resets the cooldown of |cffffffffRam|r and causing your next |cffffffffRam|r to critically strike%.%s*$","Próximo 3 |cffffffffGolpes Valentes|r e |cffffffffTrompaços|r causam dano aumentado em {{1}}% e concedem |cffffffffTempo|r.\n\nAo expirar, reinicia a recarga de |cffffffffAríete|r e Faz com que seu próximo |cffffffffAríete|r seja crítico."}
T[14873]={"^Regenerating Energy%. |cffffffffSong of Battle|r attack power bonus increased by (.-)%%%s*$","Regeneração de Energia. |cffffffffCanto de Batalha|r de poder de ataque aumentado em {{1}}%"}
T[14874]={"^Regenerating Energy%.%s*$","Regeneração de Energia."}
T[14907]={"^Magic Damage taken reduced by (.-)%%%. Whenever you are hit by a spell, you lose 1 stack of this effect%.%s*$","A redução do dano mágico recebido é de {{1}}%. Sempre que você é atingido com um feitiço, perde 1 acúmulo deste efeito."}
T[14938]={"^Damage Taken reduced by (.-)%%%. Healing Taken increased by (.-)%%%.\n\nThis effect occurs when the Guardian drops below 35%% of their Maximum Health%.%s*$","A redução do dano recebido é de {{1}}%. O aumento da cura recebida é de {{2}}%.\n\nEste efeito se faz quando Guardião cai abaixo do 35% de sua vida Máxima."}
T[14939]={"^Teaches you Offensive Pose and Defensive Pose, two light stances to adjust your combat Focus%.%s*$","Ensina Posição Ofensiva e Posição Defensiva, dois posturas leves para ajustar seu Foco em combate."}
T[15712]={"^Melee attacks have a chance to pulverize the target, inflicting additional Weapon damage to the target and other nearby enemies around the caster%.%s*$","Os ataques de corpo a corpo têm uma chance de pulverizar o alvo, causando dano adicional de arma ao alvo e a outros inimigos próximos o conjurador."}
T[15969]={"^Your melee special attacks have a chance to pulverize the target, inflicting additional (.-)%% Weapon damage to the target and other nearby enemies%. Damage is reduced as further targets are away from the caster%. %(1 sec%. cd%) %(1%.5 ppm%)%s*$","Seus ataques especiais corpo a corpo têm chance de pulverizar o alvo, causando {{1}}% de dano da arma adicional ao alvo e aos inimigos próximos. O dano diminui conforme a distância dos alvos em relação ao conjurador. (1 s de recarga) (1,5 PPM)."}
T[15973]={"^Your melee special attacks have a chance to pulverize the target, inflicting additional (.-)%% Weapon damage to the target and other nearby enemies%. Damage is reduced as further targets are away from the caster%. %(1 sec%. cd%) %(1%.5 ppm%)%s*$","Seus ataques especiais corpo a corpo têm chance de pulverizar o alvo, causando {{1}}% de dano da arma adicional ao alvo e aos inimigos próximos. O dano diminui conforme a distância dos alvos em relação ao conjurador. (1 s de recarga) (1,5 PPM)."}
T[15975]={"^Your melee special attacks have a chance to pulverize the target, inflicting additional (.-)%% Weapon damage to the target and other nearby enemies%. Damage is reduced as further targets are away from the caster%. %(1 sec%. cd%) %(1%.5 ppm%)%s*$","Seus ataques especiais corpo a corpo têm chance de pulverizar o alvo, causando {{1}}% de dano da arma adicional ao alvo e aos inimigos próximos. O dano diminui conforme a distância dos alvos em relação ao conjurador. (1 s de recarga) (1,5 PPM)."}
