T[17819]={"^Deals (.-) Damage to all enemies within 20 yards%.%s*$","Causa {{1}} de dano a todos os inimigos dentro de 20 metros."}
T[18635]={"^At 5 stacks, you will be stunned for (.-)%.%s*$","Com 5 acúmulos, te atordoarão durante {{1}}."}
T[18691]={"^|cffffffffGladiator's Net|r applies 3 stacks of |cffffffffTendon Slash%.|r%s*$","|cffffffffRede do Gladiador|r aplica 3 acúmulos de |cffffffffTalho de tendão.|r"}
T[18718]={"^Makes melee attacks generate a stack of |cFFFFFFFFBattle Inspired|r which allows usage of Song of Battle at 5 stacks%.%s*$","Permite que os ataques corpo a corpo gerem um acúmulo de |cFFFFFFFFInspirado ao Combate|r, o qual permite usar Canto do Combate com 5 acúmulos."}
